// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.lead_type = "Medium-Value";
  if (item.json.lead_score ==3) 
    item.json.lead_type = "Medium-Value";
  if (item.json.lead_score < 1) 
    item.json.lead_type = "Low-Value";


}

